mapper.select:

SELECT COUNT(*) 
FROM access_log 
WHERE access_time >= #{startTime} 
  AND access_time < #{endTime}


SELECT COUNT(DISTINCT ip) 
FROM access_log 
WHERE access_time >= #{startTime} 
  AND access_time < #{endTime}


SELECT url AS url, COUNT(*) AS count
FROM access_log
WHERE access_time >= #{startTime}
  AND access_time < #{endTime}
GROUP BY url
ORDER BY COUNT(*) DESC
LIMIT #{limit}
